#!/usr/bin/env bash
# @generated by @metaobjectsdev/pack-cloudflare (cloudflare-doctor) — hand edits are kept by a three-way merge on regeneration; meta verify --codegen checks only the generated parts.
# Checks app.client acme::docs::Docs.site on Cloudflare against the model, for one environment, by name only:
# the deploy token and account id are in the vault; every secret the model declares is in the vault
# and on the Pages project; each domain answers.
# Exits 1 when a check fails. It prints names, never a value.
#
# Needs: keys-axi, jq, curl, and what deploy/cloudflare/wrangler.sh needs.
#
#   bash deploy/cloudflare/doctor.sh <environment>
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 2

ENVIRONMENT="${1:-}"
FAIL=0
ok() { echo "ok   $*"; }
bad() { echo "FAIL $*"; FAIL=1; }
KEYS_AXI="${KEYS_AXI:-$(command -v keys-axi || echo "$HOME/.local/bin/keys-axi")}"
[ -x "$KEYS_AXI" ] || { echo "doctor: keys-axi is not installed" >&2; exit 2; }
for tool in jq curl npx; do
  command -v "$tool" >/dev/null || { echo "doctor: $tool is not installed" >&2; exit 2; }
done

# in_vault <vault project> <vault environment> <NAME>...
in_vault() {
  local names
  names=$("$KEYS_AXI" ls --project "$1" --env "$2" --json | jq -r '.secrets[].name') || { bad "cannot list vault scope $1/$2"; return; }
  local where="$1/$2"; shift 2
  for n in "$@"; do
    if grep -qx "$n" <<<"$names"; then ok "$n is in the vault ($where)"; else bad "$n is not in the vault ($where)"; fi
  done
}

# answers <url>
answers() {
  if curl -fsS -o /dev/null --max-time 10 "$1"; then ok "$1 answers"; else bad "$1 does not answer 2xx"; fi
}

case "$ENVIRONMENT" in
  production)
    in_vault deploy dev CLOUDFLARE_PAGES_TOKEN_DOCS CLOUDFLARE_ACCOUNT_ID
    answers https://docs.example.com/
    ;;
  preview)
    in_vault deploy dev CLOUDFLARE_PAGES_TOKEN_DOCS CLOUDFLARE_ACCOUNT_ID
    ;;
  *) echo 'usage: bash deploy/cloudflare/doctor.sh <environment> (environments: production, preview)' >&2; exit 2 ;;
esac

exit "$FAIL"
